// WebRA's own pixel art (art/pixel-data.js, generated by tools/gen_pixel_art.py):
// 8-bit frames in Red Alert's style for actors Red Alert has no art for
// (OpenRA drew theirs itself, data/source/bits.txt): the oil derrick, the
// Black Hawk and the Mobile Flak. The frames use Red Alert's index
// conventions (content/palette.js: 0 transparent, 4 shadow, 80 to 95 the
// owner's colour) on WebRA's own palette, so they go through the same path
// as the original graphics: a pose table per slot (js/sprites.js buildAtlas
// `slots`) from OpenRA-style sequences over the frames (content/sequences.js
// resolveSequence: facings anticlockwise from north), with or without the
// original graphics installed (installed art and texture packs come first,
// slot by slot). The body is the first slot, the second holds the turret or
// the rotor (idle on the ground, move in the air), like the original art
// (content/atlas.js). The engine draws these slots the way it draws
// pre-rendered art (gameart.js applyGameArt: rotor sequences, turrets at
// their Turreted offset).
//
// Images are stored at two atlas pixels per world pixel, like WebRA's vector
// art (sprites.js RES), so they stay crisp with the linear sampler of WebRA's
// atlas as well as the nearest one of the original graphics.

import { PIXEL_ART, PIXEL_PALETTE } from './pixel-data.js';
import { rect } from './kit.js';
import { indexedImage, modes, poseTable } from '../content/atlas.js';
import { ACTOR_SHADOW, SHADOW_ALPHA, paletteLookup } from '../content/palette.js';
import { resolveSequence } from '../content/sequences.js';

/** Atlas pixels per world pixel of the stored images. */
export const PIXEL_RES = 2;

/** Sine of OpenRA's classic camera pitch (engine render.rs CLASSIC_PITCH_SIN). */
const PITCH = 654 / 1024;

const decode = (b64) => Uint8Array.from(atob(b64), (ch) => ch.charCodeAt(0));

let lookupCache = null;
/** The colour and team mask lookup of WebRA's palette (content/palette.js paletteLookup). */
export function pixelLookup() {
  lookupCache ??= paletteLookup(decode(PIXEL_PALETTE), { remap: true, shadow: ACTOR_SHADOW });
  return lookupCache;
}

/** The pixel art of an actor id (art/pixel-data.js PIXEL_ART), or null. */
export function pixelArtOf(id) {
  return PIXEL_ART[String(id).toUpperCase()] ?? null;
}

/**
 * Frame `k` of `art` as an 8-bit frame ({ width, height, data }) with
 * `left` and `top`, its place relative to the art's origin.
 */
export function pixelFrame(art, k) {
  const [left, top, width, height, b64] = art.frames[k];
  return { width, height, data: decode(b64), left, top };
}

/** The sequence definition (content/sequences.js) of a pixel art pose. */
const sequenceDef = (seq) => ({ start: seq.start, length: seq.length ?? 1, facings: seq.facings ?? 1, tick: seq.tick ?? 40 });

/** An atlas image scaled up `n` times (nearest), drawn `1 / n` the size: the same world size. */
function upscaled(img, n) {
  const w = img.width * n;
  const h = img.height * n;
  const color = new Uint8ClampedArray(w * h * 4);
  const mask = img.mask ? new Uint8Array(w * h) : null;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const s = Math.floor(y / n) * img.width + Math.floor(x / n);
      color.set(img.color.subarray(s * 4, s * 4 + 4), (y * w + x) * 4);
      if (mask) mask[y * w + x] = img.mask[s];
    }
  }
  return { width: w, height: h, color, mask, offset: img.offset, scale: (img.scale ?? 1) / n };
}

/**
 * The pose table of one part of an actor's pixel art ('body' or 'second'):
 * each pose plays its sequence over the frames (all facings, looping), the
 * other poses fall back like loaded original art (content/atlas.js
 * poseTable). Images are centred like the original graphics: structures on
 * the footprint plus `centerOffset`, units on their position, plus the art's
 * offset. Null without pixel art for that part.
 */
export function pixelPartArt(a, part) {
  const art = pixelArtOf(a.id);
  const seqs = art?.[part];
  if (!seqs) return null;
  const lookup = pixelLookup();
  const base = a.kind === 'building' ? (a.centerOffset ?? [0, 0]) : [0, 0];
  const images = [];
  const index = new Map();
  const imageOf = (k) => {
    if (!index.has(k)) {
      const f = pixelFrame(art, k);
      const offset = [base[0] + art.offset[0] + f.left + f.width / 2, base[1] + art.offset[1] + f.top + f.height / 2];
      index.set(k, images.length);
      images.push(upscaled(indexedImage(f, null, lookup, offset), PIXEL_RES));
    }
    return index.get(k);
  };
  const have = {};
  for (const [pose, seq] of Object.entries(seqs)) {
    const def = sequenceDef(seq);
    const resolved = resolveSequence(def, art.frames.length);
    have[pose] = modes(resolved, resolved.fileFrames.map(imageOf), def);
  }
  const poses = poseTable(have);
  return poses ? { images, poses } : null;
}

/** The body's pose table (pixelPartArt). */
export function pixelBodyArt(a) {
  return pixelPartArt(a, 'body');
}

/**
 * Slots (2t body, 2t + 1 turret or rotor) of the actors with pixel art:
 * slot -> pose table, for js/sprites.js buildAtlas, which uses each where
 * no texture pack or original art has the slot. Aliases of one id share
 * one table.
 */
export function pixelSlots(actors) {
  const slots = new Map();
  const shared = new Map();
  actors.forEach((a, t) => {
    if (a.kind === 'proxy' || !pixelArtOf(a.id)) return;
    ['body', 'second'].forEach((part, k) => {
      const key = `${String(a.id).toUpperCase()}|${part}|${a.kind === 'building' ? (a.centerOffset ?? [0, 0]).join(',') : ''}`;
      if (!shared.has(key)) shared.set(key, pixelPartArt(a, part));
      const art = shared.get(key);
      if (art) slots.set(2 * t + k, art);
    });
  });
  return slots;
}

/** Paint frame `k` of `art` pixel by pixel with its top left at (left, top) (P: js/sprites.js colour pass). */
function paintFrame(ctx, P, art, k, left, top) {
  const frame = pixelFrame(art, k);
  const lookup = pixelLookup();
  const shadow = `rgba(0,0,0,${(SHADOW_ALPHA / 255).toFixed(3)})`;
  for (let y = 0; y < frame.height; y++) {
    for (let x = 0; x < frame.width; x++) {
      const v = frame.data[y * frame.width + x];
      if (v === 0) continue;
      const o = v * 4;
      let fill;
      if (lookup.color[o + 3] !== 255) fill = P.c(shadow);
      else if (lookup.mask[v]) fill = P.team(lookup.color[o] / 255);
      else fill = P.c(`rgb(${lookup.color[o]},${lookup.color[o + 1]},${lookup.color[o + 2]})`);
      rect(ctx, fill, left + x, top + y, 1, 1);
    }
  }
}

/**
 * A draw function (js/sprites.js [w, h, draw]) painting the idle frame of
 * `id`'s pixel art into its footprint box (`a`: rules_json record): the
 * editor's and sidebar's icons of structures (sprites.js drawIcon) and the
 * atlas slot before the pose table replaces it.
 */
export function pixelDraw(a) {
  const art = pixelArtOf(a.id);
  if (!art?.body) return null;
  const k = art.body.idle.start;
  const f = art.frames[k];
  const left = ((a.width ?? 1) * 24) / 2 + art.offset[0] + f[0];
  const top = ((a.height ?? 1) * 24) / 2 + art.offset[1] + f[1];
  return (ctx, P) => paintFrame(ctx, P, art, k, left, top);
}

/**
 * A unit's entry for js/sprites.js UNIT_DRAW from its pixel art, facing
 * north like WebRA's drawings: `body` the first facing of the idle body,
 * `turret` the first frame of the second part's idle sequence (the turret at
 * its Turreted offset `turretOffset` [forward, right] in world units, or
 * the stopped rotor), both [w, h, draw] in one box centred on the unit, so
 * icons and the atlas slots before the pose tables replace them line up.
 * Null without pixel art.
 */
export function pixelUnitDraw(id, turretOffset = [0, 0]) {
  const art = pixelArtOf(id);
  if (!art?.body) return null;
  const bodyK = art.body.idle.start;
  const secondK = art.second ? art.second.idle.start : -1;
  // OpenRA's classic placement facing north: forward is up, shortened by the pitch.
  const shift = [(turretOffset[1] * 24) / 1024, (-turretOffset[0] * 24 * PITCH) / 1024];
  const parts = [[bodyK, 0, 0]];
  if (secondK >= 0) parts.push([secondK, shift[0], shift[1]]);
  let half = [1, 1];
  for (const [k, dx, dy] of parts) {
    const [l, t, w, h] = art.frames[k];
    half = [Math.max(half[0], Math.abs(l + dx), Math.abs(l + w + dx)), Math.max(half[1], Math.abs(t + dy), Math.abs(t + h + dy))];
  }
  const [W, H] = [Math.ceil(half[0]) * 2, Math.ceil(half[1]) * 2];
  const draw = ([k, dx, dy]) => [W, H, (ctx, P) => paintFrame(ctx, P, art, k, W / 2 + art.frames[k][0] + dx, H / 2 + art.frames[k][1] + dy)];
  return { body: draw(parts[0]), turret: parts[1] ? draw(parts[1]) : undefined };
}

/**
 * Draw `id`'s pixel art cameo (64 x 48, opaque, its own colours: Red Alert's
 * cameos are not remapped) scaled into (0, 0, width, height) of ctx with
 * nearest sampling. False when the art has no cameo.
 */
export function drawPixelCameo(ctx, id, width, height) {
  const cam = pixelArtOf(id)?.cameo;
  if (!cam) return false;
  const [w, h, b64] = cam;
  const data = decode(b64);
  const lookup = pixelLookup();
  const sx = width / w;
  const sy = height / h;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const o = data[y * w + x] * 4;
      ctx.fillStyle = `rgb(${lookup.color[o]},${lookup.color[o + 1]},${lookup.color[o + 2]})`;
      const x0 = Math.round(x * sx);
      const y0 = Math.round(y * sy);
      ctx.fillRect(x0, y0, Math.round((x + 1) * sx) - x0, Math.round((y + 1) * sy) - y0);
    }
  }
  return true;
}
